from collections import Counter
h,w=len(test),len(test[0]); modes=[];pur=[]
for row in test:
 c,n=Counter(row).most_common(1)[0];modes.append(c);pur.append(n/w)
print(Counter(modes), [(i,modes[i],round(pur[i],2)) for i in range(h) if i<5 or i%4==0])
# reproduce selection
best=None
for color in set(modes):
 for period in range(2,min(11,h)):
  for residue in range(period):
   ids=[r for r,v in enumerate(modes) if r%period==residue and v==color]
   if ids:
    score=sum(pur[r] for r in ids)
    if best is None or score>best[0]:best=(score,color,period,residue,len(ids))
print(best)
print('firstlast',modes[0],modes[-1])

